#!/usr/bin/env python3
"""起動の秒の端数を変えて test_review_loop_wait.TestDeadline と同じ起動をし、結果を記録する。"""
import os, subprocess, sys, tempfile, threading, time, json

SCRIPT = sys.argv[1]
fractions = [0.05, 0.3, 0.6, 0.85, 0.92, 0.95, 0.96, 0.97, 0.98, 0.99, 0.995]
repeat = int(sys.argv[2]) if len(sys.argv) > 2 else 3
rows = []

def wait_until(frac):
    now = time.time()
    t = int(now) + frac
    if t <= now + 0.05:
        t += 1
    time.sleep(t - now)

def run(mode, frac):
    with tempfile.TemporaryDirectory() as d:
        wait_until(frac)
        started = time.time()
        proc = subprocess.Popen(["bash", SCRIPT, d, "x", "0.1"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        timers = []
        if mode == "place":
            timers = [threading.Timer(5.5, lambda: open(os.path.join(d, "end"), "w").close())]
        for t in timers:
            t.start()
        out, err = proc.communicate(timeout=30)
        for t in timers:
            t.cancel()
        return proc.returncode, out.strip(), time.time() - started, started - int(started)

for mode in ("nothing", "place"):
    for frac in fractions:
        for i in range(repeat):
            rc, out, elapsed, actual = run(mode, frac)
            rows.append({"mode": mode, "frac": round(actual, 3), "rc": rc, "out": out, "elapsed": round(elapsed, 3)})
            print(json.dumps(rows[-1]), flush=True)
