#!/usr/bin/env python3
"""シグナルを無視する設定 (SIG_IGN) で起動した ps に、実行中にシグナルを送り、結果を数える。"""
import collections, os, signal, subprocess, time

def trial(sig):
    # 親のプロセスが SIG_IGN にして起動すると、子に無視が引き継がれる (スクリプトのサブシェルの trap '' と同じ)
    old = signal.signal(sig, signal.SIG_IGN)
    p = subprocess.Popen(["ps", "-A", "-o", "pgid=,stat="], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, restore_signals=False)
    signal.signal(sig, old)
    # ps の起動を待つ: exec の後の /proc/<pid>/comm が ps になるまで
    while True:
        try:
            if open(f"/proc/{p.pid}/comm").read().strip() == "ps":
                break
        except OSError:
            break
    os.kill(p.pid, sig)
    out, err = p.communicate()
    return p.returncode, len(out.splitlines()), err.strip().splitlines()[:2]

for sig in (signal.SIGINT, signal.SIGTERM, signal.SIGHUP):
    c = collections.Counter()
    sample = None
    for _ in range(300):
        rc, lines, err = trial(sig)
        c[(rc, lines > 0)] += 1
        if rc != 0 and sample is None:
            sample = err
    print(sig.name, dict(c), sample)
EOF
